                ],
                ["quizzes", "Quizzes"],
                [
                  "programming",
                  "Programming",
                ],
                ["exams", "Exams"],
                [
                  "not_started",
                  "Not started",
                ],
                [
                  "in_progress",
                  "In progress",
                ],
                [
                  "submitted",
                  "Submitted",
                ],
                [
                  "completed",
                  "Completed",
                ],
                ["overdue", "Overdue"],
              ] as Array<
                [
                  AssignmentFilter,
                  string,
