"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import toast from "react-hot-toast";
import {
  collection,
  doc,
  getDoc,
  onSnapshot,
  query,
  where,
} from "firebase/firestore";

import AssignmentClassStep from "@/components/teacher/AssignmentClassStep";
import AssignmentDetailsStep from "@/components/teacher/AssignmentDetailsStep";
import AssignmentResourceStep from "@/components/teacher/AssignmentResourceStep";
import AssignmentReviewStep from "@/components/teacher/AssignmentReviewStep";
import Card from "@/components/ui/Card";
import { useAuth } from "@/contexts/AuthContext";
import { db } from "@/lib/firebase";
import { createAssignment } from "@/services/assignmentService";
import { createProgrammingAssignment } from "@/services/programmingAssignmentService";
import { createExamAssignment } from "@/services/examAssignmentService";
import { getExamQuestionSetById } from "@/services/examQuestionService";
import { getTeacherResources } from "@/services/teacherResourceService";
import { createResourceAssignment } from "@/services/resourceAssignmentService";

import type {
  AssignmentWizardClass,
  AssignmentWizardData,
  AssignmentWizardResource,
  AssignmentWizardStep,
} from "@/types/assignmentWizard";

const initialWizardData: AssignmentWizardData = {
  resource: null,
  selectedClassIds: [],
  dueDate: "",
  instructions: "",
  deliveryMode: "practice",
};

export default function AssignmentWizardPage() {
  const { user, loading: authLoading } =
    useAuth();
  const searchParams = useSearchParams();
  const quizId = searchParams.get("quizId");
  const contentType = searchParams.get("contentType");
  const contentId = searchParams.get("contentId");

  const [step, setStep] =
    useState<AssignmentWizardStep>(
      "resource",
    );
  const [wizardData, setWizardData] =
    useState<AssignmentWizardData>(
      initialWizardData,
    );
  const [classes, setClasses] =
    useState<
      AssignmentWizardClass[]
    >([]);
  const [loadingClasses, setLoadingClasses] =
    useState(true);
  const [loadingResource, setLoadingResource] =
    useState(false);
  const [submitting, setSubmitting] =
    useState(false);

  useEffect(() => {
    if (authLoading) return;

    if (!user) {
      setClasses([]);
      setLoadingClasses(false);
      return;
    }

    const classesQuery = query(
      collection(db, "classes"),
      where(
        "teacherId",
        "==",
        user.uid,
      ),
    );

    const unsubscribe = onSnapshot(
      classesQuery,
      (snapshot) => {
        const loadedClasses: AssignmentWizardClass[] =
          snapshot.docs.map(
            (classDocument) => {
              const data =
                classDocument.data();

              return {
                id: classDocument.id,
                name:
                  data.name ||
                  "Untitled Class",
                yearGroup:
                  data.yearGroup ||
                  "Not specified",
              };
            },
          );

        loadedClasses.sort((a, b) =>
          a.name.localeCompare(
            b.name,
          ),
        );

        setClasses(loadedClasses);
        setLoadingClasses(false);
      },
      (error) => {
        console.error(
          "Failed to load classes:",
          error,
        );
        toast.error(
          "Could not load your classes.",
        );
        setClasses([]);
        setLoadingClasses(false);
      },
    );

    return unsubscribe;
  }, [authLoading, user]);

  useEffect(() => {
    if (!quizId || !user) return;

    let cancelled = false;

    async function loadSavedQuiz() {
      setLoadingResource(true);

      try {
        const quizSnapshot =
          await getDoc(
            doc(
              db,
              "generatedQuizzes",
              quizId as string,
            ),
          );

        if (cancelled) return;

        if (!quizSnapshot.exists()) {
          toast.error(
            "The selected quiz could not be found.",
          );
          return;
        }

        const data =
          quizSnapshot.data();

        if (
          data.teacherId &&
          data.teacherId !== user?.uid
        ) {
          toast.error(
            "You cannot assign another teacher's quiz.",
          );
          return;
        }

        const questionCount =
          typeof data.questionCount === "number"
            ? data.questionCount
            : Array.isArray(data.questions)
              ? data.questions.length
              : 0;

        const resource: AssignmentWizardResource = {
          id: quizSnapshot.id,
          title:
            data.title ||
            "Untitled AI Quiz",
          description:
            data.description ||
            "Complete the assigned AI quiz.",
          resourceType:
            "ai-quiz",
          resourceId:
            quizSnapshot.id,
          questionCount,
          examBoard:
            typeof data.examBoard === "string"
              ? data.examBoard
              : undefined,
          qualification:
            data.qualification === "A_LEVEL"
              ? "A_LEVEL"
              : data.qualification === "GCSE"
                ? "GCSE"
                : undefined,
          estimatedTime:
            typeof data.estimatedTime === "string"
              ? data.estimatedTime
              : undefined,
        };

        setWizardData(
          (current) => ({
            ...current,
            resource,
            instructions:
              current.instructions ||
              data.description ||
              "Complete the quiz and review your answers.",
          }),
        );

        setStep("classes");

        toast.success(
          "Quiz loaded into the assignment wizard.",
        );
      } catch (error) {
        console.error(
          "Failed to load saved quiz:",
          error,
        );

        toast.error(
          "Could not load the selected quiz.",
        );
      } finally {
        if (!cancelled) {
          setLoadingResource(false);
        }
      }
    }

    void loadSavedQuiz();

    return () => {
      cancelled = true;
    };
  }, [quizId, user]);

  useEffect(() => {
    if (!contentType || !contentId || !user) return;

    /*
     * Capture the guarded values as stable non-null strings before
     * entering the nested async function.
     *
     * TypeScript does not preserve the narrowing of search-param values
     * inside an async closure unless we store them after the guard.
     */
    const selectedContentType = contentType;
    const selectedContentId = contentId;
    const teacherId = user.uid;

    let cancelled = false;

    async function loadContent() {
      setLoadingResource(true);
      try {
        if (selectedContentType === "teaching-resource") {
          const resources = await getTeacherResources(teacherId);
          if (cancelled) return;
          const saved = resources.find(
            (item) => item.id === selectedContentId,
          );
          if (!saved) {
            toast.error("The selected teaching resource could not be found.");
            return;
          }
          if (saved.status !== "published") {
            toast.error("Publish this teaching resource before assigning it.");
            return;
          }

          const resource: AssignmentWizardResource = {
            id: saved.id,
            title: saved.title,
            description: saved.content.overview || `Complete ${saved.title}.`,
            resourceType: "teaching-resource",
            resourceId: saved.id,
            topicTitle: saved.topic,
            examBoard: saved.examBoard,
            qualification:
              saved.yearGroup === "A Level" ||
              saved.yearGroup === "Year 12" ||
              saved.yearGroup === "Year 13"
                ? "A_LEVEL"
                : "GCSE",
          };

          setWizardData((current) => ({
            ...current,
            resource,
            instructions: current.instructions || resource.description,
          }));
          setStep("classes");
          toast.success("Teaching resource loaded into the assignment wizard.");
          return;
        }

        if (selectedContentType === "exam-paper") {
          const questionSet = await getExamQuestionSetById(selectedContentId);
          if (cancelled) return;
          if (!questionSet || questionSet.teacherId !== teacherId) {
            toast.error("The selected exam paper could not be found.");
            return;
          }
          if (questionSet.status !== "published") {
            toast.error("Publish this question set before assigning it.");
            return;
          }

          const resource: AssignmentWizardResource = {
            id: questionSet.id,
            title: questionSet.title,
            description: `${questionSet.questionCount} questions · ${questionSet.totalMarks} marks`,
            resourceType: "exam-paper",
            resourceId: questionSet.id,
            examTopic: questionSet.topic,
            examBoard: questionSet.examBoard,
            examQualification: questionSet.qualification,
            qualification: questionSet.qualification === "A_LEVEL" ? "A_LEVEL" : "GCSE",
            questionCount: questionSet.questionCount,
            totalMarks: questionSet.totalMarks,
          };

          setWizardData((current) => ({
            ...current,
            resource,
            instructions:
              current.instructions ||
              "Complete the written assessment under the conditions set by your teacher.",
          }));
          setStep("classes");
          toast.success("Exam paper loaded into the assignment wizard.");
        }
      } catch (error) {
        console.error("Failed to load content into assignment wizard:", error);
        toast.error(error instanceof Error ? error.message : "The selected content could not be loaded.");
      } finally {
        if (!cancelled) setLoadingResource(false);
      }
    }

    void loadContent();
    return () => { cancelled = true; };
  }, [contentType, contentId, user]);

  function selectResource(
    resource: AssignmentWizardResource,
  ) {
    const quizResource =
      resource.resourceType === "quiz" ||
      resource.resourceType === "ai-quiz";

    setWizardData((current) => ({
      ...current,
      resource,
      instructions:
        current.instructions ||
        resource.description,
      deliveryMode: quizResource
        ? current.deliveryMode
        : "practice",
    }));
  }

  function toggleClass(
    classId: string,
  ) {
    setWizardData((current) => {
      const alreadySelected =
        current.selectedClassIds.includes(
          classId,
        );

      return {
        ...current,
        selectedClassIds:
          alreadySelected
            ? current.selectedClassIds.filter(
                (selectedId) =>
                  selectedId !== classId,
              )
            : [
                ...current.selectedClassIds,
                classId,
              ],
      };
    });
  }

  async function submitAssignments() {
    if (!user) {
      toast.error(
        "You must be logged in as a teacher.",
      );
      return;
    }

    if (!wizardData.resource) {
      toast.error(
        "Choose a resource first.",
      );
      return;
    }

    if (
      wizardData.selectedClassIds.length ===
      0
    ) {
      toast.error(
        "Choose at least one class.",
      );
      return;
    }

    if (
      !wizardData.dueDate ||
      !wizardData.instructions.trim()
    ) {
      toast.error(
        "Add a due date and instructions.",
      );
      return;
    }

    setSubmitting(true);

    try {
      if (
        wizardData.resource.resourceType ===
        "programming-challenge"
      ) {
        await Promise.all(
          wizardData.selectedClassIds.map(
            (selectedClassId) =>
              createProgrammingAssignment(
                {
                  teacherId: user.uid,
                  classId:
                    selectedClassId,
                  challengeId:
                    wizardData.resource!
                      .resourceId,
                  dueDate:
                    wizardData.dueDate,
                  instructions:
                    wizardData.instructions.trim(),
                },
              ),
          ),
        );
      } else if (
        wizardData.resource.resourceType ===
        "teaching-resource"
      ) {
        await Promise.all(
          wizardData.selectedClassIds.map(async (selectedClassId) => {
            const selectedClass = classes.find((item) => item.id === selectedClassId);
            if (!selectedClass) throw new Error("A selected class could not be found.");

            const classSnapshot = await getDoc(doc(db, "classes", selectedClassId));
            if (!classSnapshot.exists()) throw new Error("A selected class could not be found.");
            const classData = classSnapshot.data();
            const studentIds = Array.isArray(classData.studentIds)
              ? classData.studentIds.filter(
                  (value): value is string =>
                    typeof value === "string" && Boolean(value.trim()),
                )
              : [];

            await createResourceAssignment({
              resourceId: wizardData.resource!.resourceId,
              resourceTitle: wizardData.resource!.title,
              resourceTopic: wizardData.resource!.topicTitle || "Teaching resource",
              resourceType: "teacher-resource",
              teacherId: user.uid,
              teacherName: user.displayName || "Teacher",
              classId: selectedClassId,
              className: selectedClass.name,
              instructions: wizardData.instructions.trim(),
              dueDate: new Date(`${wizardData.dueDate}T23:59:59`),
              studentIds,
            });
          }),
        );
      } else if (
        wizardData.resource.resourceType ===
        "lesson"
      ) {
        await Promise.all(
          wizardData.selectedClassIds.map(
            async (
              selectedClassId,
            ) => {
              const selectedClass =
                classes.find(
                  (item) =>
                    item.id ===
                    selectedClassId,
                );

              if (!selectedClass) {
                throw new Error(
                  "A selected class could not be found.",
                );
              }

              const classSnapshot =
                await getDoc(
                  doc(
                    db,
                    "classes",
                    selectedClassId,
                  ),
                );

              if (
                !classSnapshot.exists()
              ) {
                throw new Error(
                  "A selected class could not be found.",
                );
              }

              const classData =
                classSnapshot.data();

              const studentIds =
                Array.isArray(
                  classData.studentIds,
                )
                  ? classData.studentIds.filter(
                      (
                        value,
                      ): value is string =>
                        typeof value ===
                          "string" &&
                        Boolean(
                          value.trim(),
                        ),
                    )
                  : [];

              await createResourceAssignment(
                {
                  resourceId:
                    wizardData.resource!
                      .resourceId,
                  resourceTitle:
                    wizardData.resource!
                      .title,
                  resourceTopic:
                    wizardData.resource!
                      .topicTitle ||
                    "Interactive lesson",
                  resourceType:
                    "lesson",
                  teacherId:
                    user.uid,
                  teacherName:
                    user.displayName ||
                    "Teacher",
                  classId:
                    selectedClassId,
                  className:
                    selectedClass.name,
                  instructions:
                    wizardData.instructions.trim(),
                  dueDate:
                    new Date(
                      `${wizardData.dueDate}T23:59:59`,
                    ),
                  studentIds,
                },
              );
            },
          ),
        );
      } else if (
        wizardData.resource.resourceType ===
        "exam-paper"
      ) {
        const questionSet =
          await getExamQuestionSetById(
            wizardData.resource.resourceId,
          );

        if (!questionSet) {
          throw new Error(
            "The selected exam paper could not be found in the Question Bank.",
          );
        }

        await Promise.all(
          wizardData.selectedClassIds.map(
            async (
              selectedClassId,
            ) => {
              const selectedClass =
                classes.find(
                  (item) =>
                    item.id ===
                    selectedClassId,
                );

              if (!selectedClass) {
                throw new Error(
                  "A selected class could not be found.",
                );
              }

              const classSnapshot =
                await getDoc(
                  doc(
                    db,
                    "classes",
                    selectedClassId,
                  ),
                );

              if (
                !classSnapshot.exists()
              ) {
                throw new Error(
                  "A selected class could not be found.",
                );
              }

              const classData =
                classSnapshot.data();

              const studentIds =
                Array.isArray(
                  classData.studentIds,
                )
                  ? classData.studentIds.filter(
                      (
                        value,
                      ): value is string =>
                        typeof value ===
                          "string" &&
                        Boolean(
                          value.trim(),
                        ),
                    )
                  : [];

              await createExamAssignment({
                teacherId:
                  user.uid,
                teacherName:
                  user.displayName ||
                  "Teacher",
                classId:
                  selectedClassId,
                className:
                  selectedClass.name,
                studentIds,
                questionSetId:
                  questionSet.id,
                questionSetTitle:
                  questionSet.title,
                questionSetSnapshot:
                  questionSet.content,
                title:
                  wizardData.resource!
                    .title,
                instructions:
                  wizardData.instructions.trim(),
                dueDate:
                  new Date(
                    `${wizardData.dueDate}T23:59:59`,
                  ),
              });
            },
          ),
        );
      } else if (
        wizardData.resource.resourceType === "quiz" ||
        wizardData.resource.resourceType === "ai-quiz"
      ) {
        const isAIQuiz =
          wizardData.resource.resourceType === "ai-quiz";

        await Promise.all(
          wizardData.selectedClassIds.map(
            (selectedClassId) =>
              createAssignment({
                teacherId: user.uid,
                classId: selectedClassId,
                title: wizardData.resource!.title,
                description:
                  wizardData.instructions.trim(),
                type: "quiz",
                resourceId:
                  wizardData.resource!.resourceId,
                dueDate: wizardData.dueDate,
                quizSource: isAIQuiz
                  ? "ai-generated"
                  : "built-in",
                deliveryMode:
                  wizardData.deliveryMode,
              }),
          ),
        );
      } else {
        throw new Error(
          "This assignment type is not yet supported.",
        );
      }

      toast.success(
        `${
          wizardData.resource.resourceType ===
          "programming-challenge"
            ? "Programming assignment"
            : wizardData.resource.resourceType ===
                "teaching-resource"
              ? "Resource assignment"
              : wizardData.resource.resourceType ===
                  "lesson"
              ? "Lesson assignment"
              : wizardData.resource.resourceType ===
                  "exam-paper"
                ? "Exam assignment"
                : wizardData.resource.resourceType ===
                    "ai-quiz"
                  ? "AI quiz assignment"
                  : wizardData.resource.resourceType ===
                      "quiz"
                    ? "Quiz assignment"
                    : "Assignment"
        } created for ${
          wizardData.selectedClassIds.length
        } ${
          wizardData.selectedClassIds.length ===
          1
            ? "class"
            : "classes"
        }.`,
      );

      setWizardData(
        initialWizardData,
      );
      setStep("resource");
    } catch (error) {
      console.error(
        "Assignment wizard error:",
        error,
      );

      toast.error(
        error instanceof Error
          ? error.message
          : "Could not create the assignments.",
      );
    } finally {
      setSubmitting(false);
    }
  }

  if (
    authLoading ||
    loadingResource
  ) {
    return (
      <main className="flex min-h-[60vh] items-center justify-center">
        <div className="text-center">
          <div className="mx-auto h-12 w-12 animate-spin rounded-full border-4 border-indigo-200 border-t-indigo-600" />

          <p className="mt-4 font-semibold text-slate-600">
            Preparing assignment wizard...
          </p>
        </div>
      </main>
    );
  }

  return (
    <div className="space-y-8">
      <Card className="border-0 bg-gradient-to-r from-emerald-700 via-teal-700 to-cyan-700 text-white">
        <div className="flex flex-col gap-6 md:flex-row md:items-center md:justify-between">
          <div>
            <p className="text-sm font-semibold uppercase tracking-wide text-emerald-100">
              Teacher Portal
            </p>

            <h1 className="mt-3 text-4xl font-extrabold">
              Assignment Wizard
            </h1>

            <p className="mt-3 max-w-2xl text-emerald-100">
              Choose a resource or programming challenge, select classes,
              add a deadline and create assignments in one guided workflow.
            </p>
          </div>

          <Link
            href="/teacher/assignments"
            className="rounded-xl bg-white px-5 py-3 text-center font-bold text-teal-700 transition hover:bg-emerald-50"
          >
            ← Assignments
          </Link>
        </div>
      </Card>

      <WizardProgress
        currentStep={step}
      />

      {step === "resource" && (
        <AssignmentResourceStep
          selectedResource={
            wizardData.resource
          }
          onSelect={selectResource}
          onNext={() =>
            setStep("classes")
          }
        />
      )}

      {step === "classes" && (
        <AssignmentClassStep
          classes={classes}
          selectedClassIds={
            wizardData.selectedClassIds
          }
          loading={loadingClasses}
          onToggleClass={
            toggleClass
          }
          onBack={() =>
            setStep("resource")
          }
          onNext={() =>
            setStep("details")
          }
        />
      )}

      {step === "details" && (
        <div className="space-y-6">
          {(wizardData.resource?.resourceType === "quiz" ||
            wizardData.resource?.resourceType === "ai-quiz") && (
            <Card>
              <p className="text-sm font-semibold uppercase tracking-wide text-indigo-600">
                Quiz delivery mode
              </p>

              <h2 className="mt-2 text-2xl font-bold text-slate-900">
                How should students take this quiz?
              </h2>

              <p className="mt-2 text-slate-600">
                Practice keeps the normal quiz experience. Assessment marks the
                assignment for monitored Exam Mode delivery.
              </p>

              <div className="mt-6 grid gap-4 md:grid-cols-2">
                <button
                  type="button"
                  onClick={() =>
                    setWizardData((current) => ({
                      ...current,
                      deliveryMode: "practice",
                    }))
                  }
                  className={`rounded-2xl border-2 p-5 text-left transition ${
                    wizardData.deliveryMode === "practice"
                      ? "border-teal-500 bg-teal-50"
                      : "border-slate-200 bg-white hover:border-teal-300"
                  }`}
                >
                  <p className="font-black text-slate-950">
                    Practice quiz
                  </p>

                  <p className="mt-2 text-sm leading-6 text-slate-600">
                    Standard quiz player with feedback, XP and normal navigation.
                  </p>

                  <p className="mt-3 text-xs font-bold uppercase tracking-wide text-teal-700">
                    Default
                  </p>
                </button>

                <button
                  type="button"
                  onClick={() =>
                    setWizardData((current) => ({
                      ...current,
                      deliveryMode: "assessment",
                    }))
                  }
                  className={`rounded-2xl border-2 p-5 text-left transition ${
                    wizardData.deliveryMode === "assessment"
                      ? "border-indigo-600 bg-indigo-50"
                      : "border-slate-200 bg-white hover:border-indigo-300"
                  }`}
                >
                  <p className="font-black text-slate-950">
                    Assessment / test
                  </p>

                  <p className="mt-2 text-sm leading-6 text-slate-600">
                    Intended for monitored Exam Mode delivery with integrity
                    monitoring and restricted navigation.
                  </p>

                  <p className="mt-3 text-xs font-bold uppercase tracking-wide text-indigo-700">
                    Monitored
                  </p>
                </button>
              </div>

              {wizardData.deliveryMode === "assessment" && (
                <div className="mt-5 rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm leading-6 text-amber-900">
                  This assignment will be stored as an assessment quiz. The next
                  wiring step will route assessment quizzes through the existing
                  Exam Mode integrity shell; practice quizzes remain unchanged.
                </div>
              )}
            </Card>
          )}

          <AssignmentDetailsStep
            dueDate={wizardData.dueDate}
            instructions={
              wizardData.instructions
            }
            onDueDateChange={(value) =>
              setWizardData(
                (current) => ({
                  ...current,
                  dueDate: value,
                }),
              )
            }
            onInstructionsChange={(value) =>
              setWizardData(
                (current) => ({
                  ...current,
                  instructions: value,
                }),
              )
            }
            onBack={() =>
              setStep("classes")
            }
            onNext={() =>
              setStep("review")
            }
          />
        </div>
      )}

      {step === "review" && (
        <AssignmentReviewStep
          data={wizardData}
          classes={classes}
          submitting={submitting}
          onBack={() =>
            setStep("details")
          }
          onSubmit={
            submitAssignments
          }
        />
      )}
    </div>
  );
}

function WizardProgress({
  currentStep,
}: {
  currentStep: AssignmentWizardStep;
}) {
  const steps: Array<{
    id: AssignmentWizardStep;
    label: string;
  }> = [
    {
      id: "resource",
      label: "Resource",
    },
    {
      id: "classes",
      label: "Classes",
    },
    {
      id: "details",
      label: "Details",
    },
    {
      id: "review",
      label: "Review",
    },
  ];

  const currentIndex =
    steps.findIndex(
      (item) =>
        item.id === currentStep,
    );

  return (
    <Card>
      <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
        {steps.map(
          (item, index) => {
            const complete =
              index < currentIndex;
            const active =
              item.id ===
              currentStep;

            return (
              <div
                key={item.id}
                className={`rounded-xl border p-4 text-center ${
                  active
                    ? "border-teal-500 bg-teal-50 text-teal-700"
                    : complete
                      ? "border-green-300 bg-green-50 text-green-700"
                      : "border-slate-200 bg-slate-50 text-slate-500"
                }`}
              >
                <p className="text-sm font-bold">
                  {complete
                    ? "✓"
                    : index + 1}
                </p>

                <p className="mt-1 font-semibold">
                  {item.label}
                </p>
              </div>
            );
          },
        )}
      </div>
    </Card>
  );
}

"use client";

import Link from "next/link";
import { useParams } from "next/navigation";
import {
  ChangeEvent,
  ReactNode,
  useCallback,
  useEffect,
  useMemo,
  useState,
} from "react";
import {
  AlertCircle,
  ArrowLeft,
  BookOpen,
  CalendarDays,
  CheckCircle2,
  Clock3,
  Download,
  ExternalLink,
  Loader2,
  Search,
  Users,
  XCircle,
} from "lucide-react";
import { doc, getDoc } from "firebase/firestore";

import Card from "@/components/ui/Card";
import Skeleton from "@/components/ui/Skeleton";
import { useAuth } from "@/contexts/AuthContext";
import { db } from "@/lib/firebase";
import {
  getAssignmentById,
  getStudentAssignmentProgress,
  ResourceAssignment,
  StudentAssignmentProgress,
  StudentAssignmentStatus,
} from "@/services/resourceAssignmentService";

type StudentProfile = {
  id: string;
  name: string;
  email: string;
};

type StudentProgressRow = {
  student: StudentProfile;
  progress: StudentAssignmentProgress;
};

type StatusFilter = "all" | StudentAssignmentStatus;

function formatDate(value: Date | null, includeTime = false): string {
  if (!value) {
    return "—";
  }

  return new Intl.DateTimeFormat(
    "en-GB",
    includeTime
      ? {
          day: "2-digit",
          month: "short",
          year: "numeric",
          hour: "2-digit",
          minute: "2-digit",
        }
      : {
          day: "2-digit",
          month: "long",
          year: "numeric",
        },
  ).format(value);
}

function formatResourceType(value: string): string {
  return value
    .replace(/[-_]/g, " ")
    .replace(/\b\w/g, (character) => character.toUpperCase());
}

function formatStatus(status: StudentAssignmentStatus): string {
  if (status === "in_progress") {
    return "In Progress";
  }

  if (status === "completed") {
    return "Completed";
  }

  return "Not Started";
}

function escapeCsvValue(value: string): string {
  return `"${value.replace(/"/g, '""')}"`;
}

function getDueDateInformation(dueDate: Date | null): {
  label: string;
  overdue: boolean;
} {
  if (!dueDate) {
    return {
      label: "No due date",
      overdue: false,
    };
  }

  const today = new Date();
  const due = new Date(dueDate);

  today.setHours(0, 0, 0, 0);
  due.setHours(0, 0, 0, 0);

  const differenceInDays = Math.ceil(
    (due.getTime() - today.getTime()) / (1000 * 60 * 60 * 24),
  );

  if (differenceInDays < 0) {
    const overdueDays = Math.abs(differenceInDays);

    return {
      label: `${overdueDays} ${overdueDays === 1 ? "day" : "days"} overdue`,
      overdue: true,
    };
  }

  if (differenceInDays === 0) {
    return {
      label: "Due today",
      overdue: false,
    };
  }

  if (differenceInDays === 1) {
    return {
      label: "Due tomorrow",
      overdue: false,
    };
  }

  return {
    label: `${differenceInDays} days remaining`,
    overdue: false,
  };
}

export default function TeacherResourceAssignmentPage() {
  const params = useParams<{
    assignmentId: string;
  }>();

  const assignmentId = params.assignmentId;
  const { user } = useAuth();

  const [assignment, setAssignment] = useState<ResourceAssignment | null>(null);

  const [rows, setRows] = useState<StudentProgressRow[]>([]);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [searchTerm, setSearchTerm] = useState("");

  const [statusFilter, setStatusFilter] = useState<StatusFilter>("all");

  const [exporting, setExporting] = useState(false);

  const loadAssignment = useCallback(async () => {
    if (!assignmentId || !user?.uid) {
      return;
    }

    try {
      setLoading(true);
      setError("");

      const loadedAssignment = await getAssignmentById(assignmentId);

      if (!loadedAssignment) {
        setAssignment(null);
        setRows([]);

        setError("This resource assignment could not be found.");

        return;
      }

      if (loadedAssignment.teacherId !== user.uid) {
        setAssignment(null);
        setRows([]);

        setError("You do not have permission to view this assignment.");

        return;
      }

      const loadedRows = await Promise.all(
        loadedAssignment.studentIds.map(async (studentId) => {
          const [profileSnapshot, progress] = await Promise.all([
            getDoc(doc(db, "users", studentId)),
            getStudentAssignmentProgress(loadedAssignment.id, studentId),
          ]);

          const profileData = profileSnapshot.exists()
            ? profileSnapshot.data()
            : null;

          return {
            student: {
              id: studentId,
              name: profileData?.name || "Student",
              email: profileData?.email || "No email available",
            },
            progress,
          } satisfies StudentProgressRow;
        }),
      );

      loadedRows.sort((first, second) =>
        first.student.name.localeCompare(second.student.name),
      );

      setAssignment(loadedAssignment);
      setRows(loadedRows);
    } catch (caughtError) {
      console.error("Failed to load assignment progress:", caughtError);

      setAssignment(null);
      setRows([]);

      setError(
        caughtError instanceof Error
          ? caughtError.message
          : "The assignment dashboard could not be loaded.",
      );
    } finally {
      setLoading(false);
    }
  }, [assignmentId, user]);

  useEffect(() => {
    void loadAssignment();
  }, [loadAssignment]);

  const completedRows = useMemo(
    () => rows.filter(({ progress }) => progress.status === "completed"),
    [rows],
  );

  const inProgressRows = useMemo(
    () => rows.filter(({ progress }) => progress.status === "in_progress"),
    [rows],
  );

  const notStartedRows = useMemo(
    () => rows.filter(({ progress }) => progress.status === "not_started"),
    [rows],
  );

  const completionPercentage =
    rows.length > 0
      ? Math.round((completedRows.length / rows.length) * 100)
      : 0;

  const filteredRows = useMemo(() => {
    const search = searchTerm.trim().toLowerCase();

    return rows.filter(({ student, progress }) => {
      const matchesStatus =
        statusFilter === "all" || progress.status === statusFilter;

      const matchesSearch =
        !search ||
        student.name.toLowerCase().includes(search) ||
        student.email.toLowerCase().includes(search);

      return matchesStatus && matchesSearch;
    });
  }, [rows, searchTerm, statusFilter]);

  const dueInformation = useMemo(
    () => getDueDateInformation(assignment?.dueDate ?? null),
    [assignment?.dueDate],
  );

  function handleSearchChange(event: ChangeEvent<HTMLInputElement>) {
    setSearchTerm(event.target.value);
  }

  function exportCsv() {
    if (!assignment) {
      return;
    }

    try {
      setExporting(true);

      const headings = [
        "Student Name",
        "Email",
        "Status",
        "Started At",
        "Completed At",
        "Assignment",
        "Class",
        "Due Date",
      ];

      const records = rows.map(({ student, progress }) => [
        student.name,
        student.email,
        formatStatus(progress.status),
        formatDate(progress.startedAt, true),
        formatDate(progress.completedAt, true),
        assignment.resourceTitle,
        assignment.className,
        formatDate(assignment.dueDate),
      ]);

      const csvContent = [
        headings.map(escapeCsvValue).join(","),
        ...records.map((record) => record.map(escapeCsvValue).join(",")),
      ].join("\n");

      const blob = new Blob([csvContent], {
        type: "text/csv;charset=utf-8;",
      });

      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");

      const safeTitle = assignment.resourceTitle
        .replace(/[^a-z0-9]+/gi, "-")
        .replace(/^-|-$/g, "")
        .toLowerCase();

      anchor.href = url;
      anchor.download = `${safeTitle || "assignment-progress"}-progress.csv`;

      document.body.appendChild(anchor);
      anchor.click();
      anchor.remove();

      URL.revokeObjectURL(url);
    } finally {
      setExporting(false);
    }
  }

  if (loading) {
    return (
      <div className="space-y-8">
        <Skeleton className="h-72 w-full rounded-3xl" />

        <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-4">
          <Skeleton className="h-32 rounded-3xl" />
          <Skeleton className="h-32 rounded-3xl" />
          <Skeleton className="h-32 rounded-3xl" />
          <Skeleton className="h-32 rounded-3xl" />
        </div>

        <Skeleton className="h-96 w-full rounded-3xl" />
      </div>
    );
  }

  if (!assignment || error) {
    return (
      <Card className="rounded-3xl border border-red-200 bg-red-50 p-8 text-center">
        <AlertCircle className="mx-auto h-10 w-10 text-red-600" />

        <h1 className="mt-5 text-2xl font-black text-red-950">
          Assignment unavailable
        </h1>

        <p className="mx-auto mt-3 max-w-xl text-sm text-red-800">
          {error || "This assignment could not be loaded."}
        </p>

        <div className="mt-6 flex flex-col items-center justify-center gap-3 sm:flex-row">
          <button
            type="button"
            onClick={() => {
              void loadAssignment();
            }}
            className="rounded-xl bg-red-600 px-5 py-3 text-sm font-bold text-white"
          >
            Try again
          </button>

          <Link
            href="/teacher/assignments"
            className="rounded-xl border border-red-300 bg-white px-5 py-3 text-sm font-bold text-red-700"
          >
            Back to assignments
          </Link>
        </div>
      </Card>
    );
  }

  return (
    <div className="space-y-8">
      <section className="rounded-3xl bg-gradient-to-br from-emerald-700 via-teal-700 to-cyan-700 p-7 text-white shadow-xl sm:p-9">
        <div className="flex flex-col gap-8 xl:flex-row xl:justify-between">
          <div className="max-w-4xl">
            <Link
              href="/teacher/assignments"
              className="inline-flex items-center gap-2 text-sm font-bold text-emerald-100 hover:text-white"
            >
              <ArrowLeft className="h-4 w-4" />
              All assignments
            </Link>

            <div className="mt-6 flex flex-wrap gap-2">
              <span className="rounded-full bg-white/15 px-3 py-1.5 text-xs font-bold">
                {formatResourceType(assignment.resourceType)}
              </span>

              <span className="rounded-full bg-white/15 px-3 py-1.5 text-xs font-bold">
                {assignment.className}
              </span>

              <span className="rounded-full bg-white/15 px-3 py-1.5 text-xs font-bold capitalize">
                {assignment.status}
              </span>
            </div>

            <p className="mt-5 text-sm font-bold uppercase tracking-[0.18em] text-emerald-100">
              Resource assignment
            </p>

            <h1 className="mt-2 text-3xl font-black sm:text-4xl">
              {assignment.resourceTitle}
            </h1>

            <p className="mt-3 font-semibold text-emerald-100">
              {assignment.resourceTopic}
            </p>

            {assignment.instructions && (
              <p className="mt-5 max-w-3xl whitespace-pre-line text-sm leading-7 text-emerald-50">
                {assignment.instructions}
              </p>
            )}

            <div className="mt-6 flex flex-wrap gap-x-6 gap-y-3 text-sm text-emerald-100">
              <span className="inline-flex items-center gap-2">
                <Users className="h-4 w-4" />
                {rows.length} {rows.length === 1 ? "student" : "students"}
              </span>

              <span className="inline-flex items-center gap-2">
                <CalendarDays className="h-4 w-4" />
                Due {formatDate(assignment.dueDate)}
              </span>

              <span
                className={`inline-flex items-center gap-2 font-bold ${
                  dueInformation.overdue ? "text-amber-200" : ""
                }`}
              >
                <Clock3 className="h-4 w-4" />
                {dueInformation.label}
              </span>
            </div>
          </div>

          <div className="w-full rounded-3xl border border-white/20 bg-white/10 p-6 xl:w-80">
            <p className="text-sm font-bold text-emerald-100">Completion</p>

            <p className="mt-1 text-4xl font-black">{completionPercentage}%</p>

            <div className="mt-5 h-3 overflow-hidden rounded-full bg-white/20">
              <div
                className="h-full rounded-full bg-white"
                style={{
                  width: `${completionPercentage}%`,
                }}
              />
            </div>

            <p className="mt-3 text-sm text-emerald-100">
              {completedRows.length} of {rows.length} students completed
            </p>

            <div className="mt-6 grid gap-3">
              <Link
                href={`/teacher/resources/${assignment.resourceId}`}
                className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl bg-white px-4 py-3 text-sm font-bold text-teal-700"
              >
                <BookOpen className="h-4 w-4" />
                View resource
                <ExternalLink className="h-4 w-4" />
              </Link>

              <button
                type="button"
                onClick={exportCsv}
                disabled={exporting || rows.length === 0}
                className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl border border-white/30 bg-white/10 px-4 py-3 text-sm font-bold text-white disabled:opacity-50"
              >
                {exporting ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Download className="h-4 w-4" />
                )}
                Export CSV
              </button>
            </div>
          </div>
        </div>
      </section>

      <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-4">
        <SummaryCard
          label="Total Students"
          value={rows.length}
          description="Assigned students"
          icon={<Users className="h-6 w-6" />}
          iconClassName="bg-blue-50 text-blue-600"
        />

        <SummaryCard
          label="Completed"
          value={completedRows.length}
          description={`${completionPercentage}% completion`}
          icon={<CheckCircle2 className="h-6 w-6" />}
          iconClassName="bg-emerald-50 text-emerald-600"
        />

        <SummaryCard
          label="In Progress"
          value={inProgressRows.length}
          description="Currently working"
          icon={<Clock3 className="h-6 w-6" />}
          iconClassName="bg-amber-50 text-amber-600"
        />

        <SummaryCard
          label="Not Started"
          value={notStartedRows.length}
          description="May need support"
          icon={<XCircle className="h-6 w-6" />}
          iconClassName="bg-slate-100 text-slate-600"
        />
      </div>

      <Card className="overflow-hidden rounded-3xl border border-slate-200 p-0">
        <div className="border-b border-slate-200 p-6 sm:p-7">
          <div className="flex flex-col gap-5 xl:flex-row xl:items-end xl:justify-between">
            <div>
              <p className="text-sm font-bold uppercase tracking-[0.16em] text-teal-600">
                Student progress
              </p>

              <h2 className="mt-2 text-2xl font-black text-slate-950">
                Completion tracker
              </h2>
            </div>

            <div className="flex flex-col gap-3 sm:flex-row">
              <label className="relative block">
                <Search className="pointer-events-none absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />

                <input
                  type="search"
                  value={searchTerm}
                  onChange={handleSearchChange}
                  placeholder="Search students..."
                  className="min-h-11 w-full rounded-xl border border-slate-300 py-3 pl-11 pr-4 text-sm sm:w-72"
                />
              </label>

              <select
                value={statusFilter}
                onChange={(event) =>
                  setStatusFilter(event.target.value as StatusFilter)
                }
                className="min-h-11 rounded-xl border border-slate-300 bg-white px-4 py-3 text-sm font-semibold"
              >
                <option value="all">All statuses</option>
                <option value="completed">Completed</option>
                <option value="in_progress">In progress</option>
                <option value="not_started">Not started</option>
              </select>
            </div>
          </div>
        </div>

        {rows.length === 0 ? (
          <EmptyState
            title="No students assigned"
            description="No students are currently assigned to this resource."
          />
        ) : filteredRows.length === 0 ? (
          <EmptyState
            title="No matching students"
            description="Try changing your search or status filter."
          />
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full">
              <thead className="bg-slate-50">
                <tr className="text-left text-xs font-bold uppercase tracking-wide text-slate-500">
                  <th className="px-6 py-4">Student</th>
                  <th className="px-6 py-4">Status</th>
                  <th className="px-6 py-4">Started</th>
                  <th className="px-6 py-4">Completed</th>
                  <th className="px-6 py-4">Last activity</th>
                </tr>
              </thead>

              <tbody className="divide-y divide-slate-100">
                {filteredRows.map(({ student, progress }) => (
                  <tr key={student.id} className="hover:bg-slate-50">
                    <td className="px-6 py-5">
                      <div className="flex items-center gap-3">
                        <StudentAvatar name={student.name} />

                        <div>
                          <p className="font-bold text-slate-950">
                            {student.name}
                          </p>

                          <p className="mt-1 text-sm text-slate-500">
                            {student.email}
                          </p>
                        </div>
                      </div>
                    </td>

                    <td className="px-6 py-5">
                      <StatusBadge status={progress.status} />
                    </td>

                    <td className="px-6 py-5 text-sm text-slate-600">
                      {formatDate(progress.startedAt, true)}
                    </td>

                    <td className="px-6 py-5 text-sm text-slate-600">
                      {formatDate(progress.completedAt, true)}
                    </td>

                    <td className="px-6 py-5 text-sm text-slate-600">
                      {formatDate(progress.updatedAt, true)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {rows.length > 0 && (
          <div className="border-t border-slate-200 bg-slate-50 px-6 py-4 text-sm font-semibold text-slate-500">
            Showing {filteredRows.length} of {rows.length} students
          </div>
        )}
      </Card>
    </div>
  );
}

function SummaryCard({
  label,
  value,
  description,
  icon,
  iconClassName,
}: {
  label: string;
  value: number;
  description: string;
  icon: ReactNode;
  iconClassName: string;
}) {
  return (
    <Card className="rounded-3xl border border-slate-200 p-6">
      <div className="flex items-center justify-between gap-4">
        <div>
          <p className="text-sm font-bold text-slate-500">{label}</p>

          <p className="mt-2 text-3xl font-black text-slate-950">{value}</p>

          <p className="mt-1 text-sm text-slate-500">{description}</p>
        </div>

        <div
          className={`flex h-12 w-12 items-center justify-center rounded-2xl ${iconClassName}`}
        >
          {icon}
        </div>
      </div>
    </Card>
  );
}

function StatusBadge({ status }: { status: StudentAssignmentStatus }) {
  if (status === "completed") {
    return (
      <span className="inline-flex items-center gap-1.5 rounded-full bg-emerald-100 px-3 py-1.5 text-xs font-bold text-emerald-700">
        <CheckCircle2 className="h-3.5 w-3.5" />
        Completed
      </span>
    );
  }

  if (status === "in_progress") {
    return (
      <span className="inline-flex items-center gap-1.5 rounded-full bg-amber-100 px-3 py-1.5 text-xs font-bold text-amber-700">
        <Clock3 className="h-3.5 w-3.5" />
        In Progress
      </span>
    );
  }

  return (
    <span className="inline-flex items-center gap-1.5 rounded-full bg-slate-100 px-3 py-1.5 text-xs font-bold text-slate-600">
      <XCircle className="h-3.5 w-3.5" />
      Not Started
    </span>
  );
}

function StudentAvatar({ name }: { name: string }) {
  const initials = name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase();

  return (
    <div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-teal-100 text-sm font-black text-teal-700">
      {initials || "ST"}
    </div>
  );
}

function EmptyState({
  title,
  description,
}: {
  title: string;
  description: string;
}) {
  return (
    <div className="p-10 text-center">
      <Users className="mx-auto h-10 w-10 text-slate-400" />

      <h3 className="mt-4 text-xl font-black text-slate-950">{title}</h3>

      <p className="mx-auto mt-2 max-w-lg text-sm text-slate-500">
        {description}
      </p>
    </div>
  );
}

"use client";

import {
  type FormEvent,
  useEffect,
  useMemo,
  useState,
} from "react";
import Link from "next/link";
import toast from "react-hot-toast";

import Card from "@/components/ui/Card";
import Skeleton from "@/components/ui/Skeleton";
import { useAuth } from "@/contexts/AuthContext";

import {
  createTeacherClass,
  getTeacherClasses,
  type TeacherClass,
} from "@/services/classService";

import type {
  ExamBoard,
  Qualification,
} from "@/types/user";

import {
  getUnifiedTeacherAssignments,
  type UnifiedTeacherAssignment,
} from "@/services/unifiedTeacherAssignmentService";

type StatusFilter =
  | "active"
  | "archived"
  | "all";

function defaultAcademicYear(): string {
  const now = new Date();

  const year =
    now.getFullYear();

  /*
   * Treat August onward as preparation for the new UK academic year.
   */
  const startYear =
    now.getMonth() >= 7
      ? year
      : year - 1;

  return `${startYear}/${startYear + 1}`;
}

function qualificationLabel(
  qualification:
    Qualification | "",
): string {
  if (
    qualification ===
    "A_LEVEL"
  ) {
    return "A Level";
  }

  return qualification || "Not set";
}

export default function TeacherClassesPage() {
  const {
    user,
    profile,
    loading: authLoading,
    profileReady,
  } = useAuth();

  const [classes, setClasses] =
    useState<
      TeacherClass[]
    >([]);

  const [
    unifiedAssignments,
    setUnifiedAssignments,
  ] = useState<
    UnifiedTeacherAssignment[]
  >([]);

  const [
    loadingClasses,
    setLoadingClasses,
  ] = useState(true);

  const [
    showForm,
    setShowForm,
  ] = useState(false);

  const [
    className,
    setClassName,
  ] = useState("");

  const [
    yearGroup,
    setYearGroup,
  ] = useState("");

  const [subject, setSubject] =
    useState(
      "Computer Science",
    );

  const [
    academicYear,
    setAcademicYear,
  ] = useState(
    defaultAcademicYear(),
  );

  const [
    qualification,
    setQualification,
  ] =
    useState<
      Qualification | ""
    >("GCSE");

  const [
    examBoard,
    setExamBoard,
  ] =
    useState<
      ExamBoard | ""
    >("OCR");

  const [
    submitting,
    setSubmitting,
  ] = useState(false);

  const [
    searchTerm,
    setSearchTerm,
  ] = useState("");

  const [
    statusFilter,
    setStatusFilter,
  ] =
    useState<StatusFilter>(
      "active",
    );

  async function loadClasses() {
    if (!user?.uid) {
      setClasses([]);
      setLoadingClasses(
        false,
      );

      return;
    }

    try {
      setLoadingClasses(
        true,
      );

      const [
        loaded,
        assignmentSummary,
      ] = await Promise.all([
        getTeacherClasses(
          user.uid,
        ),
        getUnifiedTeacherAssignments(
          user.uid,
        ),
      ]);

      setClasses(
        loaded,
      );

      setUnifiedAssignments(
        assignmentSummary.assignments,
      );
    } catch (error) {
      console.error(
        "Failed to load classes:",
        error,
      );

      toast.error(
        "Could not load your classes.",
      );
    } finally {
      setLoadingClasses(
        false,
      );
    }
  }

  useEffect(() => {
    if (
      authLoading ||
      !profileReady
    ) {
      return;
    }

    void loadClasses();
  }, [
    authLoading,
    profileReady,
    user?.uid,
  ]);

  const visibleClasses =
    useMemo(() => {
      const search =
        searchTerm
          .trim()
          .toLowerCase();

      return classes.filter(
        (item) => {
          const matchesStatus =
            statusFilter ===
              "all" ||
            item.status ===
              statusFilter;

          if (
            !matchesStatus
          ) {
            return false;
          }

          if (!search) {
            return true;
          }

          return [
            item.name,
            item.subject,
            item.yearGroup,
            item.academicYear,
            item.qualification,
            item.examBoard,
          ].some(
            (value) =>
              value
                .toLowerCase()
                .includes(
                  search,
                ),
          );
        },
      );
    }, [
      classes,
      searchTerm,
      statusFilter,
    ]);

  const activeClasses =
    classes.filter(
      (item) =>
        item.status ===
        "active",
    );

  const totalStudents =
    activeClasses.reduce(
      (
        total,
        item,
      ) =>
        total +
        item.studentIds.length,
      0,
    );

  const activeClassIds =
    new Set(
      activeClasses.map(
        (item) => item.id,
      ),
    );

  const totalAssignments =
    unifiedAssignments.filter(
      (assignment) =>
        activeClassIds.has(
          assignment.classId,
        ),
    ).length;

  const assignmentCountByClass =
    useMemo(() => {
      const counts =
        new Map<string, number>();

      unifiedAssignments.forEach(
        (assignment) => {
          counts.set(
            assignment.classId,
            (counts.get(
              assignment.classId,
            ) || 0) + 1,
          );
        },
      );

      return counts;
    }, [
      unifiedAssignments,
    ]);

  async function handleCreateClass(
    event:
      FormEvent<HTMLFormElement>,
  ) {
    event.preventDefault();

    if (!user?.uid) {
      toast.error(
        "You must be logged in as a teacher.",
      );
      return;
    }

    if (
      !profile?.schoolId
    ) {
      toast.error(
        "Create or join your school organisation before creating classes.",
      );
      return;
    }

    if (
      !className.trim() ||
      !yearGroup.trim() ||
      !academicYear.trim() ||
      !qualification ||
      !examBoard
    ) {
      toast.error(
        "Complete every required class field.",
      );
      return;
    }

    try {
      setSubmitting(true);

      await createTeacherClass({
        name:
          className,

        subject,

        yearGroup,

        academicYear,

        qualification,

        examBoard,

        teacherId:
          user.uid,

        teacherName:
          profile?.name ||
          user.displayName ||
          user.email ||
          "Teacher",

        schoolId:
          profile.schoolId,
      });

      toast.success(
        "Class created successfully.",
      );

      setClassName("");
      setYearGroup("");
      setSubject(
        "Computer Science",
      );
      setAcademicYear(
        defaultAcademicYear(),
      );
      setQualification(
        "GCSE",
      );
      setExamBoard(
        "OCR",
      );
      setShowForm(false);

      await loadClasses();
    } catch (error) {
      console.error(
        "Create class error:",
        error,
      );

      toast.error(
        error instanceof Error
          ? error.message
          : "Could not create the class.",
      );
    } finally {
      setSubmitting(false);
    }
  }

  if (
    authLoading ||
    !profileReady ||
    loadingClasses
  ) {
    return (
      <div className="space-y-8">
        <Skeleton className="h-52 w-full" />

        <div className="grid grid-cols-1 gap-6 md:grid-cols-3">
          <Skeleton className="h-28" />
          <Skeleton className="h-28" />
          <Skeleton className="h-28" />
        </div>

        <Skeleton className="h-96 w-full" />
      </div>
    );
  }

  return (
    <div className="space-y-8">
      <Card className="border-0 bg-gradient-to-r from-emerald-700 via-teal-700 to-cyan-700 text-white">
        <div className="flex flex-col gap-6 md:flex-row md:items-center md:justify-between">
          <div>
            <p className="text-sm font-semibold uppercase tracking-wide text-emerald-100">
              Teacher Portal
            </p>

            <h1 className="mt-3 text-4xl font-extrabold">
              Manage Classes
            </h1>

            <p className="mt-3 max-w-2xl text-emerald-100">
              Create school-scoped teaching groups, manage curriculum settings,
              organise students and monitor assignments.
            </p>
          </div>

          <div className="flex flex-wrap gap-3">
            <Link
              href="/teacher/school"
              className="rounded-xl border border-white/30 bg-white/10 px-5 py-3 text-sm font-bold text-white transition hover:bg-white/20"
            >
              School
            </Link>

            <button
              type="button"
              onClick={() =>
                setShowForm(
                  (current) =>
                    !current,
                )
              }
              className="rounded-xl bg-white px-5 py-3 text-sm font-bold text-teal-800 shadow-sm transition hover:bg-emerald-50"
            >
              {showForm
                ? "Close form"
                : "+ Create class"}
            </button>
          </div>
        </div>
      </Card>

      {!profile?.schoolId && (
        <Card className="border border-amber-200 bg-amber-50">
          <h2 className="font-black text-amber-950">
            School setup required
          </h2>

          <p className="mt-2 text-sm leading-6 text-amber-800">
            New classes must belong to a school organisation so students remain
            isolated from other schools.
          </p>
        </Card>
      )}

      <div className="grid gap-4 md:grid-cols-3">
        <Metric
          label="Active classes"
          value={
            activeClasses.length
          }
        />

        <Metric
          label="Students"
          value={
            totalStudents
          }
        />

        <Metric
          label="Assignments"
          value={
            totalAssignments
          }
        />
      </div>

      {showForm && (
        <Card className="border border-teal-200">
          <p className="text-sm font-black uppercase tracking-wide text-teal-600">
            New teaching group
          </p>

          <h2 className="mt-2 text-2xl font-black text-slate-950">
            Create a class
          </h2>

          <form
            onSubmit={
              handleCreateClass
            }
            className="mt-6 grid gap-5 md:grid-cols-2"
          >
            <Field
              label="Class name"
              value={
                className
              }
              onChange={
                setClassName
              }
              placeholder="e.g. Year 11 CS Group"
            />

            <Field
              label="Year group"
              value={
                yearGroup
              }
              onChange={
                setYearGroup
              }
              placeholder="e.g. Year 11"
            />

            <Field
              label="Subject"
              value={
                subject
              }
              onChange={
                setSubject
              }
              placeholder="Computer Science"
            />

            <Field
              label="Academic year"
              value={
                academicYear
              }
              onChange={
                setAcademicYear
              }
              placeholder="2026/2027"
            />

            <label>
              <span className="text-sm font-bold text-slate-700">
                Qualification
              </span>

              <select
                value={
                  qualification
                }
                onChange={(
                  event,
                ) =>
                  setQualification(
                    event.target
                      .value as
                      | Qualification
                      | "",
                  )
                }
                className="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3"
              >
                <option value="GCSE">
                  GCSE
                </option>

                <option value="A_LEVEL">
                  A Level
                </option>
              </select>
            </label>

            <label>
              <span className="text-sm font-bold text-slate-700">
                Exam board
              </span>

              <select
                value={
                  examBoard
                }
                onChange={(
                  event,
                ) =>
                  setExamBoard(
                    event.target
                      .value as
                      | ExamBoard
                      | "",
                  )
                }
                className="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3"
              >
                <option value="AQA">
                  AQA
                </option>

                <option value="OCR">
                  OCR
                </option>

                <option value="EDEXCEL">
                  Pearson Edexcel
                </option>
              </select>
            </label>

            <div className="md:col-span-2">
              <button
                type="submit"
                disabled={
                  submitting ||
                  !profile?.schoolId
                }
                className="rounded-xl bg-teal-600 px-6 py-3 font-bold text-white transition hover:bg-teal-700 disabled:cursor-not-allowed disabled:opacity-60"
              >
                {submitting
                  ? "Creating..."
                  : "Create class"}
              </button>
            </div>
          </form>
        </Card>
      )}

      <Card>
        <div className="flex flex-col justify-between gap-5 xl:flex-row xl:items-end">
          <div>
            <p className="text-sm font-black uppercase tracking-wide text-slate-500">
              Class directory
            </p>

            <h2 className="mt-2 text-2xl font-black text-slate-950">
              Your classes
            </h2>
          </div>

          <div className="flex flex-col gap-3 sm:flex-row">
            <input
              type="search"
              value={
                searchTerm
              }
              onChange={(
                event,
              ) =>
                setSearchTerm(
                  event.target
                    .value,
                )
              }
              placeholder="Search classes..."
              className="min-w-[240px] rounded-xl border border-slate-300 px-4 py-3"
            />

            <select
              value={
                statusFilter
              }
              onChange={(
                event,
              ) =>
                setStatusFilter(
                  event.target
                    .value as
                    StatusFilter,
                )
              }
              className="rounded-xl border border-slate-300 px-4 py-3"
            >
              <option value="active">
                Active
              </option>

              <option value="archived">
                Archived
              </option>

              <option value="all">
                All classes
              </option>
            </select>
          </div>
        </div>

        {visibleClasses.length ===
        0 ? (
          <div className="mt-6 rounded-2xl border border-dashed border-slate-300 bg-slate-50 p-10 text-center">
            <h3 className="font-black text-slate-900">
              No classes found
            </h3>

            <p className="mt-2 text-sm text-slate-500">
              Create a class or adjust the current search/filter.
            </p>
          </div>
        ) : (
          <div className="mt-6 grid gap-5 xl:grid-cols-2">
            {visibleClasses.map(
              (
                classItem,
              ) => (
                <article
                  key={
                    classItem.id
                  }
                  className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"
                >
                  <div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-start">
                    <div>
                      <div className="flex flex-wrap gap-2">
                        <span className="rounded-full bg-teal-50 px-3 py-1 text-xs font-black uppercase text-teal-700">
                          {classItem.yearGroup ||
                            "Year group"}
                        </span>

                        <span className="rounded-full bg-blue-50 px-3 py-1 text-xs font-black text-blue-700">
                          {classItem.examBoard ||
                            "Board"}{" "}
                          {qualificationLabel(
                            classItem.qualification,
                          )}
                        </span>

                        {classItem.status ===
                          "archived" && (
                          <span className="rounded-full bg-amber-50 px-3 py-1 text-xs font-black text-amber-700">
                            Archived
                          </span>
                        )}
                      </div>

                      <h3 className="mt-3 text-xl font-black text-slate-950">
                        {classItem.name}
                      </h3>

                      <p className="mt-1 text-sm text-slate-500">
                        {classItem.subject ||
                          "Computer Science"}{" "}
                        ·{" "}
                        {classItem.academicYear ||
                          "Academic year not set"}
                      </p>
                    </div>

                    <Link
                      href={`/teacher/classes/${classItem.id}`}
                      className="shrink-0 rounded-xl bg-blue-600 px-5 py-3 text-sm font-bold text-white transition hover:bg-blue-700"
                    >
                      Open class
                    </Link>
                  </div>

                  <div className="mt-5 grid grid-cols-2 gap-3">
                    <MiniMetric
                      label="Students"
                      value={
                        classItem
                          .studentIds
                          .length
                      }
                    />

                    <MiniMetric
                      label="Assignments"
                      value={
                        assignmentCountByClass.get(
                          classItem.id,
                        ) || 0
                      }
                    />
                  </div>
                </article>
              ),
            )}
          </div>
        )}
      </Card>
    </div>
  );
}

function Metric({
  label,
  value,
}: {
  label: string;
  value: number;
}) {
  return (
    <Card>
      <p className="text-sm font-semibold text-slate-500">
        {label}
      </p>

      <p className="mt-2 text-3xl font-black text-slate-950">
        {value}
      </p>
    </Card>
  );
}

function MiniMetric({
  label,
  value,
}: {
  label: string;
  value: number;
}) {
  return (
    <div className="rounded-2xl bg-slate-50 p-4">
      <p className="text-xs font-bold uppercase tracking-wide text-slate-500">
        {label}
      </p>

      <p className="mt-1 text-xl font-black text-slate-900">
        {value}
      </p>
    </div>
  );
}

function Field({
  label,
  value,
  onChange,
  placeholder,
}: {
  label: string;
  value: string;
  onChange: (
    value: string,
  ) => void;
  placeholder: string;
}) {
  return (
    <label>
      <span className="text-sm font-bold text-slate-700">
        {label}
      </span>

      <input
        type="text"
        value={value}
        onChange={(
          event,
        ) =>
          onChange(
            event.target.value,
          )
        }
        placeholder={
          placeholder
        }
        className="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3"
      />
    </label>
  );
}

