        )}
      </Card>

      <Card className="rounded-3xl border border-teal-200 bg-teal-50 p-5">
        <div className="flex items-start gap-3">
          <BookOpenCheck className="mt-0.5 h-5 w-5 shrink-0 text-teal-700" />

          <div>
