      {currentQuestion && (
        <Card>
          <p className="text-sm font-black uppercase tracking-wide text-indigo-600">
            {currentQuestion.commandWord} Ã‚Â· {currentQuestion.type}
          </p>
          <h1 className="mt-3 whitespace-pre-wrap text-2xl font-black leading-9">
