"use client";

import { useEffect, useState } from "react";
import toast from "react-hot-toast";

import { captureInterventionBaseline } from "@/services/analytics/interventionImpactService";
import { createIntervention } from "@/services/interventionService";
import type { InterventionCandidate } from "@/services/interventionAnalyticsService";
import type { InterventionPriority } from "@/types/intervention";

export default function CreateInterventionModal({
  candidate,
  teacherId,
  teacherName,
  onClose,
  onCreated,
}: {
  candidate: InterventionCandidate | null;
  teacherId: string;
  teacherName: string;
  onClose: () => void;
  onCreated: () => void;
}) {
  const [title, setTitle] = useState("");
  const [topic, setTopic] = useState("");
  const [reason, setReason] = useState("");
  const [priority, setPriority] =
    useState<InterventionPriority>("high");
  const [pathway, setPathway] = useState<
    "lesson" | "quiz" | "exam" | "complete"
  >("complete");
  const [dueDate, setDueDate] = useState("");
  const [lessonHref, setLessonHref] = useState("");
  const [quizId, setQuizId] = useState("");
  const [examId, setExamId] = useState("");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!candidate) return;

    const date = new Date();
    date.setDate(date.getDate() + 7);

    setDueDate(date.toISOString().slice(0, 10));
    setTitle(`${candidate.priorityTopic} intervention`);
    setTopic(candidate.priorityTopic);
    setReason(candidate.recommendation);
    setPriority(
      candidate.priority === "low"
        ? "medium"
        : candidate.priority,
    );
    setLessonHref(
      `/learn?search=${encodeURIComponent(candidate.priorityTopic)}`,
    );
  }, [candidate]);

  if (!candidate) return null;

  async function submit() {
    if (!candidate) return;

    if (!teacherId.trim()) {
      toast.error("A teacher account is required.");
      return;
    }

    if (!title.trim() || !topic.trim() || !reason.trim()) {
      toast.error("Add a title, topic and reason.");
      return;
    }

    if (!dueDate) {
      toast.error("Choose a due date.");
      return;
    }

    setSaving(true);

    try {
      const createdResult = (await createIntervention({
        teacherId,
        teacherName,
        studentId: candidate.student.uid,
        studentName: candidate.student.name,
        studentEmail: candidate.student.email,
        classId: candidate.classId,
        className: candidate.className,
        title: title.trim(),
        topic: topic.trim(),
        reason: reason.trim(),
        priority,
        baselineScore: candidate.combinedAverage,
        dueDate: new Date(`${dueDate}T23:59:59`),
        pathway,
        lessonHref: lessonHref.trim(),
        quizAssignmentId: quizId.trim(),
        examAssignmentId: examId.trim(),
        xpPerStep: 25,
      })) as unknown;

      if (
        typeof createdResult === "string" &&
        createdResult.trim()
      ) {
        try {
          await captureInterventionBaseline({
            interventionId: createdResult,
            teacherId,
            studentId: candidate.student.uid,
            topic: topic.trim(),
          });
        } catch (baselineError) {
          console.error(
            "Intervention created but baseline capture failed:",
            baselineError,
          );

          toast.error(
            "Intervention created, but the analytics baseline could not be captured automatically. You can capture it from Review impact.",
          );

          onCreated();
          return;
        }
      } else {
        console.warn(
          "createIntervention did not return an intervention ID. Automatic baseline capture was skipped.",
        );
      }

      toast.success("Intervention created.");
      onCreated();
    } catch (error) {
      toast.error(
        error instanceof Error
          ? error.message
          : "Intervention could not be created.",
      );
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-4">
      <div className="max-h-[92vh] w-full max-w-3xl overflow-y-auto rounded-3xl bg-white p-6">
        <div className="flex justify-between gap-4">
          <div>
            <p className="text-sm font-bold uppercase text-teal-600">
              Create intervention
            </p>

            <h2 className="mt-2 text-2xl font-black">
              {candidate.student.name}
            </h2>

            <p className="text-sm text-slate-500">
              Baseline {candidate.combinedAverage}% · {candidate.className}
            </p>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="rounded-xl border px-4 py-2 font-bold"
          >
            Close
          </button>
        </div>

        <div className="mt-6 grid gap-4 md:grid-cols-2">
          <label className="md:col-span-2">
            <span className="text-sm font-bold">Title</span>
            <input
              value={title}
              onChange={(event) => setTitle(event.target.value)}
              className="mt-2 w-full rounded-xl border px-4 py-3"
            />
          </label>

          <label>
            <span className="text-sm font-bold">Topic</span>
            <input
              value={topic}
              onChange={(event) => setTopic(event.target.value)}
              className="mt-2 w-full rounded-xl border px-4 py-3"
            />
          </label>

          <label>
            <span className="text-sm font-bold">Priority</span>
            <select
              value={priority}
              onChange={(event) =>
                setPriority(
                  event.target.value as InterventionPriority,
                )
              }
              className="mt-2 w-full rounded-xl border px-4 py-3"
            >
              <option value="high">High</option>
              <option value="medium">Medium</option>
              <option value="low">Low</option>
            </select>
          </label>

          <label>
            <span className="text-sm font-bold">Pathway</span>
            <select
              value={pathway}
              onChange={(event) =>
                setPathway(event.target.value as typeof pathway)
              }
              className="mt-2 w-full rounded-xl border px-4 py-3"
            >
              <option value="complete">Complete pathway</option>
              <option value="lesson">Lesson only</option>
              <option value="quiz">Quiz only</option>
              <option value="exam">Exam only</option>
            </select>
          </label>

          <label>
            <span className="text-sm font-bold">Due date</span>
            <input
              type="date"
              value={dueDate}
              onChange={(event) => setDueDate(event.target.value)}
              className="mt-2 w-full rounded-xl border px-4 py-3"
            />
          </label>

          <label className="md:col-span-2">
            <span className="text-sm font-bold">Reason</span>
            <textarea
              rows={4}
              value={reason}
              onChange={(event) => setReason(event.target.value)}
              className="mt-2 w-full rounded-xl border px-4 py-3"
            />
          </label>

          {(pathway === "lesson" || pathway === "complete") && (
            <label className="md:col-span-2">
              <span className="text-sm font-bold">Lesson link</span>
              <input
                value={lessonHref}
                onChange={(event) => setLessonHref(event.target.value)}
                className="mt-2 w-full rounded-xl border px-4 py-3"
              />
            </label>
          )}

          {(pathway === "quiz" || pathway === "complete") && (
            <label>
              <span className="text-sm font-bold">
                Quiz assignment ID (optional)
              </span>
              <input
                value={quizId}
                onChange={(event) => setQuizId(event.target.value)}
                className="mt-2 w-full rounded-xl border px-4 py-3"
              />
            </label>
          )}

          {(pathway === "exam" || pathway === "complete") && (
            <label>
              <span className="text-sm font-bold">
                Exam assignment ID (optional)
              </span>
              <input
                value={examId}
                onChange={(event) => setExamId(event.target.value)}
                className="mt-2 w-full rounded-xl border px-4 py-3"
              />
            </label>
          )}
        </div>

        <div className="mt-6 flex justify-end gap-3">
          <button
            type="button"
            onClick={onClose}
            className="rounded-xl border px-5 py-3 font-bold"
          >
            Cancel
          </button>

          <button
            type="button"
            onClick={() => void submit()}
            disabled={saving}
            className="rounded-xl bg-teal-600 px-5 py-3 font-bold text-white disabled:cursor-not-allowed disabled:bg-slate-300"
          >
            {saving ? "Creating..." : "Create Intervention"}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import Link from "next/link";
import {
  Activity,
  AlertTriangle,
  CheckCircle2,
  ClipboardCheck,
  RefreshCcw,
  RotateCcw,
  Target,
} from "lucide-react";
import {
  useEffect,
  useMemo,
  useState,
} from "react";
import toast from "react-hot-toast";

import Card from "@/components/ui/Card";
import {
  captureInterventionBaseline,
  getInterventionImpact,
} from "@/services/analytics/interventionImpactService";
import {
  buildInterventionReassessmentHref,
  buildInterventionReviewCycle,
  saveInterventionReviewDecision,
} from "@/services/analytics/interventionReviewCycleService";
import type { InterventionImpact } from "@/types/interventionImpact";
import type { InterventionReviewDecision } from "@/types/interventionReviewCycle";

function delta(
  value: number | null,
  suffix = "",
): string {
  if (value === null) return "—";
  return value > 0 ? `+${value}${suffix}` : `${value}${suffix}`;
}

function decisionLabel(
  value: InterventionReviewDecision,
): string {
  switch (value) {
    case "close_successful":
      return "Close as successful";
    case "retarget":
      return "Retarget support";
    case "escalate":
      return "Escalate support";
    default:
      return "Continue intervention";
  }
}

export default function InterventionImpactCard({
  interventionId,
  teacherId,
}: {
  interventionId: string;
  teacherId: string;
}) {
  const [impact, setImpact] =
    useState<InterventionImpact | null>(null);

  const [loading, setLoading] = useState(true);
  const [savingBaseline, setSavingBaseline] = useState(false);
  const [savingDecision, setSavingDecision] = useState(false);
  const [reviewNote, setReviewNote] = useState("");
  const [error, setError] = useState("");

  async function load() {
    try {
      setLoading(true);
      setError("");

      setImpact(
        await getInterventionImpact({
          interventionId,
          teacherId,
        }),
      );
    } catch (caughtError) {
      console.error(
        "Unable to load intervention impact:",
        caughtError,
      );

      setError(
        caughtError instanceof Error
          ? caughtError.message
          : "Intervention impact could not be loaded.",
      );
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    void load();
  }, [interventionId, teacherId]);

  const review = useMemo(
    () =>
      impact
        ? buildInterventionReviewCycle(impact)
        : null,
    [impact],
  );

  if (loading) {
    return (
      <Card className="rounded-3xl border border-slate-200">
        <div className="h-56 animate-pulse rounded-2xl bg-slate-100" />
      </Card>
    );
  }

  if (!impact) {
    return error ? <Card>{error}</Card> : null;
  }

  async function captureBaseline() {
    if (!impact) {
      return;
    }

    try {
      setSavingBaseline(true);

      await captureInterventionBaseline({
        interventionId,
        teacherId,
        studentId: impact.studentId,
        topic: impact.topic,
      });

      toast.success("Intervention baseline captured.");
      await load();
    } catch (caughtError) {
      toast.error(
        caughtError instanceof Error
          ? caughtError.message
          : "Baseline could not be captured.",
      );
    } finally {
      setSavingBaseline(false);
    }
  }

  async function saveDecision(
    decision: InterventionReviewDecision,
  ) {
    if (!impact) {
      return;
    }

    try {
      setSavingDecision(true);

      await saveInterventionReviewDecision({
        interventionId,
        teacherId,
        decision,
        note: reviewNote,
      });

      toast.success(
        decision === "close_successful"
          ? "Intervention closed as successful."
          : "Intervention review saved.",
      );

      await load();
    } catch (caughtError) {
      toast.error(
        caughtError instanceof Error
          ? caughtError.message
          : "The intervention review could not be saved.",
      );
    } finally {
      setSavingDecision(false);
    }
  }

  const reassessmentHref =
    buildInterventionReassessmentHref({
      impact,
    });

  return (
    <div className="space-y-6">
      <Card className="overflow-hidden rounded-3xl border border-slate-200">
        <div className="bg-gradient-to-r from-violet-950 via-indigo-950 to-blue-900 p-6 text-white">
          <div className="flex items-center gap-2 text-blue-200">
            <Activity className="h-5 w-5" />
            <p className="text-xs font-black uppercase tracking-[0.16em]">
              Intervention impact
            </p>
          </div>

          <h2 className="mt-2 text-2xl font-black">
            Before → after review
          </h2>

          <p className="mt-2 text-sm text-white/70">
            {impact.topic}
          </p>
        </div>

        {impact.baseline === null ? (
          <div className="p-6">
            <div className="rounded-2xl border border-amber-200 bg-amber-50 p-5">
              <p className="font-black text-amber-950">
                No before-intervention baseline
              </p>

              <p className="mt-2 text-sm text-amber-800">
                {impact.summary}
              </p>

              <button
                type="button"
                disabled={savingBaseline}
                onClick={() => void captureBaseline()}
                className="mt-4 inline-flex min-h-10 items-center gap-2 rounded-xl bg-amber-700 px-4 text-xs font-black text-white disabled:opacity-60"
              >
                <Target className="h-4 w-4" />
                {savingBaseline
                  ? "Capturing..."
                  : "Capture baseline now"}
              </button>
            </div>
          </div>
        ) : (
          <>
            <div className="grid gap-4 p-6 sm:grid-cols-2 xl:grid-cols-5">
              <Metric
                label="Working grade"
                before={impact.baseline.workingGrade || "—"}
                after={impact.current.workingGrade || "—"}
                change={delta(impact.workingGradeChange)}
              />

              <Metric
                label="Grade gap"
                before={
                  impact.baseline.gradeGap === null
                    ? "—"
                    : String(impact.baseline.gradeGap)
                }
                after={
                  impact.current.gradeGap === null
                    ? "—"
                    : String(impact.current.gradeGap)
                }
                change={delta(impact.gradeGapChange)}
              />

              <Metric
                label="Attainment"
                before={`${impact.baseline.weightedPercentage}%`}
                after={`${impact.current.weightedPercentage}%`}
                change={delta(impact.attainmentChange, "%")}
              />

              <Metric
                label="Topic mastery"
                before={
                  impact.baseline.topicMastery === null
                    ? "—"
                    : `${impact.baseline.topicMastery}%`
                }
                after={
                  impact.current.topicMastery === null
                    ? "—"
                    : `${impact.current.topicMastery}%`
                }
                change={delta(impact.topicMasteryChange, "%")}
              />

              <Metric
                label="Completion"
                before={`${impact.baseline.completionRate}%`}
                after={`${impact.current.completionRate}%`}
                change={delta(impact.completionChange, "%")}
              />
            </div>

            <div className="grid gap-5 border-t border-slate-100 p-6 lg:grid-cols-2">
              <div className="rounded-2xl bg-slate-50 p-5">
                <p className="text-xs font-black uppercase tracking-wide text-slate-400">
                  Interpretation
                </p>

                <p className="mt-2 text-sm text-slate-700">
                  {impact.summary}
                </p>

                <p className="mt-3 text-xs font-black text-slate-500">
                  New evidence since baseline: {impact.evidenceChange}
                </p>
              </div>

              <div className="rounded-2xl bg-blue-50 p-5">
                <p className="text-xs font-black uppercase tracking-wide text-blue-700">
                  Recommended next action
                </p>

                <p className="mt-2 text-sm text-blue-950">
                  {impact.nextAction}
                </p>
              </div>
            </div>
          </>
        )}

        <div className="flex justify-end border-t border-slate-100 px-6 py-4">
          <button
            type="button"
            onClick={() => void load()}
            className="inline-flex min-h-10 items-center gap-2 rounded-xl border border-slate-200 px-4 text-xs font-black text-slate-700"
          >
            <RefreshCcw className="h-4 w-4" />
            Refresh impact
          </button>
        </div>
      </Card>

      {review && (
        <Card className="overflow-hidden rounded-3xl border border-teal-200">
          <div className="bg-gradient-to-r from-teal-950 to-cyan-800 p-6 text-white">
            <div className="flex items-center gap-2 text-teal-200">
              <ClipboardCheck className="h-5 w-5" />
              <p className="text-xs font-black uppercase tracking-[0.16em]">
                Review cycle
              </p>
            </div>

            <h2 className="mt-2 text-2xl font-black">
              {review.headline}
            </h2>

            <p className="mt-2 max-w-4xl text-sm leading-6 text-white/75">
              {review.explanation}
            </p>
          </div>

          <div className="grid gap-5 p-6 lg:grid-cols-2">
            <div className="rounded-2xl bg-emerald-50 p-5">
              <p className="text-xs font-black uppercase tracking-wide text-emerald-700">
                Positive signals
              </p>

              {review.successSignals.length ? (
                <ul className="mt-3 space-y-2 text-sm text-emerald-950">
                  {review.successSignals.map((item) => (
                    <li
                      key={item}
                      className="flex items-start gap-2"
                    >
                      <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-emerald-600" />
                      {item}
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="mt-3 text-sm text-emerald-900/70">
                  No material positive change is recorded yet.
                </p>
              )}
            </div>

            <div className="rounded-2xl bg-amber-50 p-5">
              <p className="text-xs font-black uppercase tracking-wide text-amber-700">
                Concerns
              </p>

              {review.concernSignals.length ? (
                <ul className="mt-3 space-y-2 text-sm text-amber-950">
                  {review.concernSignals.map((item) => (
                    <li
                      key={item}
                      className="flex items-start gap-2"
                    >
                      <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-amber-600" />
                      {item}
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="mt-3 text-sm text-amber-900/70">
                  No material decline is recorded.
                </p>
              )}
            </div>
          </div>

          <div className="border-t border-slate-100 p-6">
            {review.reassessmentRecommended && (
              <div className="mb-5 flex flex-col gap-4 rounded-2xl border border-indigo-200 bg-indigo-50 p-5 sm:flex-row sm:items-center sm:justify-between">
                <div>
                  <p className="font-black text-indigo-950">
                    Focused reassessment recommended
                  </p>

                  <p className="mt-1 text-sm text-indigo-800">
                    Assign a new task on {impact.topic}, then return here once it is graded to review the change.
                  </p>
                </div>

                <Link
                  href={reassessmentHref}
                  className="inline-flex min-h-10 shrink-0 items-center gap-2 rounded-xl bg-indigo-600 px-4 text-xs font-black text-white"
                >
                  <RotateCcw className="h-4 w-4" />
                  Assign reassessment
                </Link>
              </div>
            )}

            <label className="block">
              <span className="text-sm font-black text-slate-900">
                Teacher review note
              </span>

              <textarea
                rows={3}
                value={reviewNote}
                onChange={(event) =>
                  setReviewNote(event.target.value)
                }
                placeholder="Record why you are continuing, retargeting, closing or escalating the intervention."
                className="mt-2 w-full rounded-xl border border-slate-200 px-4 py-3 text-sm"
              />
            </label>

            <div className="mt-5 flex flex-wrap gap-3">
              <button
                type="button"
                disabled={savingDecision}
                onClick={() =>
                  void saveDecision(
                    review.recommendedDecision,
                  )
                }
                className="inline-flex min-h-10 items-center gap-2 rounded-xl bg-teal-600 px-4 text-xs font-black text-white disabled:opacity-60"
              >
                <ClipboardCheck className="h-4 w-4" />
                {savingDecision
                  ? "Saving..."
                  : decisionLabel(
                      review.recommendedDecision,
                    )}
              </button>

              {review.recommendedDecision !== "continue" && (
                <button
                  type="button"
                  disabled={savingDecision}
                  onClick={() =>
                    void saveDecision("continue")
                  }
                  className="inline-flex min-h-10 items-center rounded-xl border border-slate-200 px-4 text-xs font-black text-slate-700 disabled:opacity-60"
                >
                  Continue instead
                </button>
              )}

              {review.canCloseSuccessful &&
                review.recommendedDecision !==
                  "close_successful" && (
                  <button
                    type="button"
                    disabled={savingDecision}
                    onClick={() =>
                      void saveDecision(
                        "close_successful",
                      )
                    }
                    className="inline-flex min-h-10 items-center rounded-xl bg-emerald-600 px-4 text-xs font-black text-white disabled:opacity-60"
                  >
                    Close as successful
                  </button>
                )}
            </div>
          </div>
        </Card>
      )}
    </div>
  );
}

function Metric({
  label,
  before,
  after,
  change,
}: {
  label: string;
  before: string;
  after: string;
  change: string;
}) {
  return (
    <div className="rounded-2xl bg-slate-50 p-4">
      <p className="text-xs font-black uppercase tracking-wide text-slate-400">
        {label}
      </p>

      <p className="mt-2 text-sm text-slate-500">
        {before} →
      </p>

      <p className="mt-1 text-lg font-black text-slate-950">
        {after}
      </p>

      <p className="mt-2 text-xs font-black text-teal-700">
        Change {change}
      </p>
    </div>
  );
}

"use client";

import {
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import {
  BarChart3,
  GraduationCap,
  Search,
  ShieldCheck,
  Users,
} from "lucide-react";

import ClassProgressReportPanel from "@/components/teacher/reports/ClassProgressReportPanel";
import StudentProgressReportPanel from "@/components/teacher/reports/StudentProgressReportPanel";
import Card from "@/components/ui/Card";

import type {
  TeacherAnalyticsPortfolio,
  TeacherStudentAnalyticsRow,
} from "@/types/teacherAnalytics";

type ReportMode =
  | "class"
  | "student";

export default function ReportingWorkspace({
  teacherId,
  portfolio,
}: {
  teacherId: string;
  portfolio:
    TeacherAnalyticsPortfolio;
}) {
  const classes =
    portfolio.classes;

  const [
    mode,
    setMode,
  ] =
    useState<ReportMode>(
      "class",
    );

  const [
    selectedClassId,
    setSelectedClassId,
  ] = useState("");

  const [
    selectedStudentId,
    setSelectedStudentId,
  ] = useState("");

  const [
    studentSearch,
    setStudentSearch,
  ] = useState("");

  useEffect(() => {
    if (
      selectedClassId &&
      classes.some(
        (item) =>
          item.classId ===
          selectedClassId,
      )
    ) {
      return;
    }

    setSelectedClassId(
      classes[0]?.classId ||
        "",
    );
  }, [
    classes,
    selectedClassId,
  ]);

  const selectedClass =
    useMemo(
      () =>
        classes.find(
          (item) =>
            item.classId ===
            selectedClassId,
        ) || null,
      [
        classes,
        selectedClassId,
      ],
    );

  const students =
    useMemo(() => {
      const source =
        selectedClass?.students ||
        [];

      const term =
        studentSearch
          .trim()
          .toLowerCase();

      const ordered =
        [...source].sort(
          (
            first,
            second,
          ) =>
            first.studentName.localeCompare(
              second.studentName,
              "en-GB",
              {
                sensitivity:
                  "base",
              },
            ),
        );

      if (!term) {
        return ordered;
      }

      return ordered.filter(
        (student) =>
          [
            student.studentName,
            student.studentEmail,
            student.workingGrade ||
              "",
            student.targetGrade ||
              "",
            student.trend,
            String(
              student.interventionPriority,
            ),
          ]
            .join(" ")
            .toLowerCase()
            .includes(term),
      );
    }, [
      selectedClass,
      studentSearch,
    ]);

  useEffect(() => {
    const classStudents =
      selectedClass?.students ||
      [];

    if (
      selectedStudentId &&
      classStudents.some(
        (student) =>
          student.studentId ===
          selectedStudentId,
      )
    ) {
      return;
    }

    setSelectedStudentId(
      classStudents[0]
        ?.studentId || "",
    );
  }, [
    selectedClass,
    selectedStudentId,
  ]);

  useEffect(() => {
    setStudentSearch("");
  }, [selectedClassId]);

  const selectedStudent =
    useMemo<
      TeacherStudentAnalyticsRow | null
    >(
      () =>
        selectedClass?.students.find(
          (student) =>
            student.studentId ===
            selectedStudentId,
        ) || null,
      [
        selectedClass,
        selectedStudentId,
      ],
    );

  if (!classes.length) {
    return (
      <Card className="rounded-3xl border border-slate-200 p-8 text-center">
        <p className="font-black text-slate-950">
          No classes available for reporting
        </p>

        <p className="mt-2 text-sm text-slate-500">
          Create a class and enrol learners before generating class or student progress reports.
        </p>
      </Card>
    );
  }

  return (
    <section className="space-y-6">
      <Card className="overflow-hidden rounded-3xl border border-slate-200 p-0">
        <div className="bg-gradient-to-r from-slate-950 via-teal-950 to-cyan-900 p-6 text-white">
          <p className="text-xs font-black uppercase tracking-[0.18em] text-cyan-200">
            Reporting workspace
          </p>

          <div className="mt-2 flex flex-col gap-5 xl:flex-row xl:items-end xl:justify-between">
            <div>
              <h2 className="text-2xl font-black">
                Class and learner intelligence
              </h2>

              <p className="mt-2 max-w-3xl text-sm leading-6 text-white/70">
                Produce evidence-backed class and learner reports while preserving the exact teaching-group context for students who belong to more than one class.
              </p>
            </div>

            <div className="grid grid-cols-2 gap-2 rounded-2xl bg-white/10 p-1">
              <ModeButton
                active={
                  mode === "class"
                }
                icon={
                  <Users className="h-4 w-4" />
                }
                label="Class report"
                onClick={() =>
                  setMode(
                    "class",
                  )
                }
              />

              <ModeButton
                active={
                  mode === "student"
                }
                icon={
                  <GraduationCap className="h-4 w-4" />
                }
                label="Student report"
                onClick={() =>
                  setMode(
                    "student",
                  )
                }
              />
            </div>
          </div>
        </div>

        <div className="grid gap-4 p-6 xl:grid-cols-[1.2fr_1fr]">
          <label>
            <span className="text-xs font-black uppercase tracking-wide text-slate-400">
              Reporting class
            </span>

            <select
              value={
                selectedClassId
              }
              onChange={(
                event,
              ) =>
                setSelectedClassId(
                  event.target
                    .value,
                )
              }
              className="mt-2 min-h-11 w-full rounded-xl border border-slate-200 bg-white px-4 font-bold text-slate-900 outline-none focus:border-teal-400"
            >
              {classes.map(
                (classItem) => (
                  <option
                    key={
                      classItem.classId
                    }
                    value={
                      classItem.classId
                    }
                  >
                    {
                      classItem.className
                    }
                  </option>
                ),
              )}
            </select>
          </label>

          <div className="grid grid-cols-2 gap-3">
            <WorkspaceMetric
              label="Students"
              value={
                selectedClass?.studentCount ??
                0
              }
            />

            <WorkspaceMetric
              label="With evidence"
              value={
                selectedClass?.studentsWithEvidence ??
                0
              }
            />
          </div>
        </div>

        {mode ===
          "student" && (
          <div className="border-t border-slate-100 p-6">
            <div className="grid gap-4 lg:grid-cols-2">
              <label>
                <span className="text-xs font-black uppercase tracking-wide text-slate-400">
                  Search learners
                </span>

                <div className="relative mt-2">
                  <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />

                  <input
                    value={
                      studentSearch
                    }
                    onChange={(
                      event,
                    ) =>
                      setStudentSearch(
                        event.target
                          .value,
                      )
                    }
                    placeholder="Search name, email, working grade, target or trend"
                    className="min-h-11 w-full rounded-xl border border-slate-200 bg-white pl-10 pr-4 text-sm outline-none focus:border-violet-400"
                  />
                </div>
              </label>

              <label>
                <span className="text-xs font-black uppercase tracking-wide text-slate-400">
                  Learner
                </span>

                <select
                  value={
                    students.some(
                      (student) =>
                        student.studentId ===
                        selectedStudentId,
                    )
                      ? selectedStudentId
                      : ""
                  }
                  onChange={(
                    event,
                  ) =>
                    setSelectedStudentId(
                      event.target
                        .value,
                    )
                  }
                  className="mt-2 min-h-11 w-full rounded-xl border border-slate-200 bg-white px-4 font-bold text-slate-900 outline-none focus:border-violet-400"
                >
                  {students.length ===
                  0 ? (
                    <option value="">
                      No matching learners
                    </option>
                  ) : (
                    students.map(
                      (
                        student,
                      ) => (
                        <option
                          key={
                            student.studentId
                          }
                          value={
                            student.studentId
                          }
                        >
                          {
                            student.studentName
                          }
                          {student.workingGrade
                            ? ` · Working ${student.workingGrade}`
                            : ""}
                          {student.targetGrade
                            ? ` · Target ${student.targetGrade}`
                            : ""}
                        </option>
                      ),
                    )
                  )}
                </select>
              </label>
            </div>

            {selectedStudent && (
              <div className="mt-4 grid gap-3 rounded-2xl bg-violet-50 p-4 sm:grid-cols-2 xl:grid-cols-5">
                <ContextMetric
                  label="Class"
                  value={
                    selectedClass?.className ||
                    "—"
                  }
                />

                <ContextMetric
                  label="Working"
                  value={
                    selectedStudent.workingGrade ||
                    "—"
                  }
                />

                <ContextMetric
                  label="Target"
                  value={
                    selectedStudent.targetGrade ||
                    "Not set"
                  }
                />

                <ContextMetric
                  label="Completion"
                  value={`${selectedStudent.completionRate}%`}
                />

                <ContextMetric
                  label="Trend"
                  value={
                    selectedStudent.trend
                  }
                />
              </div>
            )}

            <div className="mt-4 flex items-start gap-3 rounded-2xl border border-violet-100 bg-white p-4 text-sm text-violet-950">
              <ShieldCheck className="mt-0.5 h-5 w-5 shrink-0 text-violet-600" />

              <p>
                <span className="font-black">
                  Class context is preserved:
                </span>{" "}
                if the learner belongs to several classes, the report remains anchored to the class selected above rather than visually merging those teaching-group records.
              </p>
            </div>
          </div>
        )}
      </Card>

      {mode === "class" ? (
        selectedClassId ? (
          <ClassProgressReportPanel
            teacherId={
              teacherId
            }
            classId={
              selectedClassId
            }
          />
        ) : null
      ) : selectedStudentId &&
        selectedClass ? (
        <StudentProgressReportPanel
          teacherId={
            teacherId
          }
          studentId={
            selectedStudentId
          }
          selectedClassId={
            selectedClass.classId
          }
          selectedClassName={
            selectedClass.className
          }
          classContext={
            selectedStudent
          }
        />
      ) : (
        <Card className="rounded-3xl border border-slate-200 p-8 text-center">
          <GraduationCap className="mx-auto h-8 w-8 text-slate-300" />

          <p className="mt-3 font-black text-slate-950">
            Select a learner
          </p>

          <p className="mt-2 text-sm text-slate-500">
            A learner must be selected before an individual progress report can be generated.
          </p>
        </Card>
      )}

      <Card className="rounded-3xl border border-cyan-100 bg-cyan-50">
        <div className="flex items-start gap-3">
          <BarChart3 className="mt-0.5 h-5 w-5 shrink-0 text-cyan-700" />

          <div>
            <p className="font-black text-cyan-950">
              One reporting source of truth
            </p>

            <p className="mt-1 text-sm leading-6 text-cyan-900">
              Reports remain grounded in the Teacher Analytics portfolio. Written-assessment QLA, evidence confidence, grade intelligence and intervention history are supporting evidence, not competing progress measures.
            </p>
          </div>
        </div>
      </Card>
    </section>
  );
}

function ModeButton({
  active,
  icon,
  label,
  onClick,
}: {
  active: boolean;
  icon: ReactNode;
  label: string;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={
        onClick
      }
      className={`inline-flex min-h-10 items-center justify-center gap-2 rounded-xl px-4 text-xs font-black transition ${
        active
          ? "bg-white text-slate-950 shadow"
          : "text-white/70 hover:bg-white/10 hover:text-white"
      }`}
    >
      {icon}
      {label}
    </button>
  );
}

function WorkspaceMetric({
  label,
  value,
}: {
  label: string;
  value: number;
}) {
  return (
    <div className="rounded-2xl bg-slate-50 p-4">
      <p className="text-xs font-black uppercase tracking-wide text-slate-400">
        {label}
      </p>

      <p className="mt-2 text-2xl font-black text-slate-950">
        {value}
      </p>
    </div>
  );
}

function ContextMetric({
  label,
  value,
}: {
  label: string;
  value:
    | string
    | number;
}) {
  return (
    <div className="rounded-xl bg-white p-3">
      <p className="text-[10px] font-black uppercase tracking-wide text-violet-400">
        {label}
      </p>

      <p className="mt-1 truncate text-sm font-black capitalize text-violet-950">
        {value}
      </p>
    </div>
  );
}

